const agentItem = $input.first().json;
const intermediateSteps = agentItem.intermediateSteps || [];

const plan = $('Head Planner').first().json.output;
const plannedCalls = (plan && plan.planned_tool_calls) || [];
const used = new Array(plannedCalls.length).fill(false);

function toolNameMatches(fullToolName, plainToolName) {
  // The MCP Client Tool node exposes remote tools as "<NodeName>_<toolName>"
  // (e.g. "MCP_Research_Tools_pricing_research"), not the bare MCP tool name
  // the Head Planner's plan uses -- match on suffix, not exact equality.
  return fullToolName === plainToolName || fullToolName.endsWith('_' + plainToolName);
}

function matchPlannedCall(toolName, toolInput) {
  const inputCompany = ((toolInput && (toolInput.company_name || toolInput.companyName)) || '').toString().trim().toLowerCase();
  for (let i = 0; i < plannedCalls.length; i++) {
    if (used[i]) continue;
    const call = plannedCalls[i];
    if (!toolNameMatches(toolName, call.tool)) continue;
    const callCompany = ((call.args && call.args.company_name) || '').toString().trim().toLowerCase();
    if (!inputCompany || callCompany === inputCompany) { used[i] = true; return call; }
  }
  for (let i = 0; i < plannedCalls.length; i++) {
    if (used[i]) continue;
    if (toolNameMatches(toolName, plannedCalls[i].tool)) { used[i] = true; return plannedCalls[i]; }
  }
  return null;
}

function classifySourceType(url) {
  if (!url) return 'community';
  const u = url.toLowerCase();
  if (u.includes('.gov')) return 'primary';
  if (/reddit\.com|trustpilot|bbb\.org/.test(u)) return 'community';
  if (/fiercetelecom|lightreading|star-banner|starbanner/.test(u)) return 'news';
  if (/spectrum\.com|att\.com|t-mobile\.com|wire3\.com/.test(u)) return 'company';
  if (/broadbandnow|jdpower|j\.d\.\s?power|acsi|parksassociates/.test(u)) return 'analyst';
  return 'community';
}

function makeEvidenceId(sourceUrl, claim) {
  let hash = 0x811c9dc5;
  const str = String(sourceUrl) + '|' + String(claim);
  for (let i = 0; i < str.length; i++) {
    hash ^= str.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  const hex = (hash >>> 0).toString(16).padStart(8, '0');
  return 'EV-' + hex;
}

const evidence = [];
const unparseable = [];

for (const step of intermediateSteps) {
  const toolName = step.action && step.action.tool;
  const toolInput = step.action && step.action.toolInput;
  const observation = step.observation;

  // The MCP Client Tool node wraps each call's result as
  // [{ response: [{ type: 'text', text: '<json-encoded actual result>' }] }],
  // not the raw MCP tool output directly -- unwrap one layer of JSON-in-JSON.
  let parsedResults = [];
  try {
    const outer = typeof observation === 'string' ? JSON.parse(observation) : observation;
    const outerArray = Array.isArray(outer) ? outer : [outer];
    for (const wrapper of outerArray) {
      if (wrapper && Array.isArray(wrapper.response)) {
        for (const part of wrapper.response) {
          if (part && typeof part.text === 'string') {
            const inner = JSON.parse(part.text);
            if (Array.isArray(inner)) parsedResults.push(...inner);
            else parsedResults.push(inner);
          }
        }
      } else {
        parsedResults.push(wrapper);
      }
    }
  } catch (e) {
    unparseable.push({ tool: toolName, args: toolInput, error: 'unparseable observation', raw: String(observation).slice(0, 300) });
    continue;
  }

  const matchedCall = matchPlannedCall(toolName, toolInput);
  const rqIds = (matchedCall && matchedCall.research_question_ids) || [];

  for (const result of parsedResults) {
    if (!result || typeof result !== 'object' || !('source_url' in result)) continue;

    const claim = String(result.excerpt || '').slice(0, 400) || 'No excerpt available';
    const excerpt = String(result.excerpt || '').slice(0, 600) || 'No excerpt available';
    const sourceType = classifySourceType(result.source_url);
    const idsToUse = rqIds.length > 0 ? rqIds : [null];

    for (const rqId of idsToUse) {
      evidence.push({
        evidence_id: makeEvidenceId(result.source_url, claim + '|' + (rqId || '')),
        research_question_id: rqId,
        claim: claim,
        source_title: result.source_title || 'Untitled source',
        source_url: result.source_url,
        source_type: sourceType,
        publication_date: result.publication_date || null,
        retrieval_timestamp: result.retrieval_timestamp || new Date().toISOString(),
        excerpt: excerpt,
        validation_status: 'unverified'
      });
    }
  }
}

const outputItem = { run_id: (plan && plan.run_id), evidence: evidence, evidence_count: evidence.length, tool_calls_planned: plannedCalls.length, tool_calls_executed: intermediateSteps.length, unparseable_observations: unparseable };
return [{ json: outputItem }];
